macro_rules! compare_number_of_method_arguments {
    () => {
        fn compare_number_of_method_arguments < 'tcx > (tcx : TyCtxt < 'tcx > , impl_m : ty :: AssocItem , trait_m : ty :: AssocItem , delay : bool ,) -> Result < () , ErrorGuaranteed > { let impl_m_fty = tcx . fn_sig (impl_m . def_id) ; let trait_m_fty = tcx . fn_sig (trait_m . def_id) ; let trait_number_args = trait_m_fty . skip_binder () . inputs () . skip_binder () . len () ; let impl_number_args = impl_m_fty . skip_binder () . inputs () . skip_binder () . len () ; if trait_number_args != impl_number_args { let trait_span = trait_m . def_id . as_local () . and_then (| def_id | { let (trait_m_sig , _) = & tcx . hir_expect_trait_item (def_id) . expect_fn () ; let pos = trait_number_args . saturating_sub (1) ; trait_m_sig . decl . inputs . get (pos) . map (| arg | { if pos == 0 { arg . span } else { arg . span . with_lo (trait_m_sig . decl . inputs [0] . span . lo ()) } }) }) . or_else (| | tcx . hir_span_if_local (trait_m . def_id)) ; let (impl_m_sig , _) = & tcx . hir_expect_impl_item (impl_m . def_id . expect_local ()) . expect_fn () ; let pos = impl_number_args . saturating_sub (1) ; let impl_span = impl_m_sig . decl . inputs . get (pos) . map (| arg | { if pos == 0 { arg . span } else { arg . span . with_lo (impl_m_sig . decl . inputs [0] . span . lo ()) } }) . unwrap_or_else (| | tcx . def_span (impl_m . def_id)) ; let mut err = struct_span_code_err ! (tcx . dcx () , impl_span , E0050 , "method `{}` has {} but the declaration in trait `{}` has {}" , trait_m . name () , potentially_plural_count (impl_number_args , "parameter") , tcx . def_path_str (trait_m . def_id) , trait_number_args) ; if let Some (trait_span) = trait_span { err . span_label (trait_span , format ! ("trait requires {}" , potentially_plural_count (trait_number_args , "parameter")) ,) ; } else { err . note_trait_signature (trait_m . name () , trait_m . signature (tcx)) ; } err . span_label (impl_span , format ! ("expected {}, found {}" , potentially_plural_count (trait_number_args , "parameter") , impl_number_args) ,) ; return Err (err . emit_unless_delay (delay)) ; } Ok (()) }
    };
}

compare_number_of_method_arguments!();